const pool=require("../config/db"),getAll=async(req,res)=>{try{const result=await pool.query("SELECT * FROM famille ORDER BY created_at DESC");res.json(result.rows)}catch(err){console.error("Erreur getAll familles:",err),res.status(500).json({erreur:err.message})}},getById=async(req,res)=>{try{const result=await pool.query("SELECT * FROM famille WHERE id = $1",[req.params.id]);if(0===result.rows.length)return res.status(404).json({erreur:"Famille non trouvee"});res.json(result.rows[0])}catch(err){console.error("Erreur getById famille:",err),res.status(500).json({erreur:err.message})}},create=async(req,res)=>{try{const{nom:nom,adresse:adresse,telephone:telephone}=req.body;if(console.log("BODY RECU:",req.body),!nom||""===nom.trim())return res.status(400).json({erreur:"Le nom est obligatoire"});const result=await pool.query("INSERT INTO famille (nom, adresse, telephone)\n       VALUES ($1, $2, $3)\n       RETURNING *",[nom.trim(),adresse&&""!==adresse.trim()?adresse.trim():null,telephone&&""!==telephone.trim()?telephone.trim():null]);res.status(201).json({message:"Famille creee avec succes",famille:result.rows[0]})}catch(err){console.error("Erreur create famille:",err),res.status(500).json({erreur:err.message})}},remove=async(req,res)=>{try{if(0===(await pool.query("DELETE FROM famille WHERE id = $1 RETURNING *",[req.params.id])).rows.length)return res.status(404).json({erreur:"Famille non trouvee"});res.json({message:"Famille supprimee avec succes"})}catch(err){console.error("Erreur remove famille:",err),res.status(500).json({erreur:err.message})}};module.exports={getAll:getAll,getById:getById,create:create,remove:remove};